{"statements": [
  {
    "id": "3.1.1a",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "text (\"must not pass\")",
    "text": "a driver MUST NOT pass a vehicle WHEN the driver is within 30 m of a pedestrian crossover",
    "sources": [
      {
        "id": "m16",
        "quote": "You must not pass any vehicle within 30 metres of a pedestrian crossover."
      }
    ],
    "flags": [],
    "links": [],
    "note": null
  },
  {
    "id": "3.4.12a",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "text (\"must stop\")",
    "text": "a driver MUST stop WHEN the driver approaches a stopped school bus with its upper alternating red lights flashing AND the driver is behind the school bus OR the driver is approaching the school bus from the front IF VIOLATED a fine AND 6 demerit points for a first offence",
    "sources": [
      {
        "id": "c1",
        "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
      },
      {
        "id": "c5",
        "quote": "If you don't stop, you can be fined heavily and get six demerit points for a first offence."
      }
    ],
    "flags": [
      {
        "code": "J",
        "span": "heavily",
        "note": "The handbook qualifies the fine as \"heavily\" but gives no amount or range."
      }
    ],
    "links": [],
    "note": "The penalty in c5 is merged into the duty statement per the method. The \"regardless of whether\" phrase is rendered as an AND/OR condition so that the median-strip exception (3.4.12d) targets the from-the-front case explicitly."
  },
  {
    "id": "3.4.12b",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "context (c1: \"must stop\")",
    "text": "a driver MUST stop at least 20 m from the school bus WHEN the school bus is stopped with its upper alternating red lights flashing AND the driver is coming from behind the school bus",
    "sources": [
      {
        "id": "c1",
        "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
      },
      {
        "id": "c2",
        "quote": "If you are coming from behind the bus, stop at least 20 metres away."
      }
    ],
    "flags": [],
    "links": [],
    "note": "c2 is a bare imperative; the legal force is inherited from c1's \"must stop\" in the same paragraph, which governs the overall school-bus stop duty."
  },
  {
    "id": "3.4.12c",
    "type": "RULE",
    "force": "LEGAL",
    "force_from": "context (c1: \"must stop\")",
    "text": "a driver MUST NOT proceed WHEN the driver approaches a stopped school bus with its upper alternating red lights flashing UNTIL the school bus moves OR the lights have stopped flashing",
    "sources": [
      {
        "id": "c1",
        "quote": "You must stop whenever you approach a stopped school bus with its upper alternating red lights flashing, regardless of whether you are behind the bus or approaching it from the front."
      },
      {
        "id": "c3",
        "quote": "Do not go until the bus moves or the lights have stopped flashing."
      }
    ],
    "flags": [],
    "links": [],
    "note": "\"Do not go\" is rendered as \"proceed.\" The legal force is inherited from c1's \"must stop\"; \"do not go\" is a bare imperative but part of the same legal duty."
  },
  {
    "id": "3.4.12d",
    "type": "EXCEPTION",
    "force": null,
    "force_from": null,
    "text": "EXCEPTION TO 3.4.12a WHEN the driver is on a road with a median strip AND the driver is approaching the school bus from the front",
    "sources": [
      {
        "id": "c4",
        "quote": "If you are on a road with a median strip, only vehicles coming from behind the bus must stop."
      }
    ],
    "flags": [],
    "links": [
      "3.4.12a"
    ],
    "note": "On a road with a median strip the duty to stop applies only to vehicles from behind; vehicles approaching from the front are exempt from the must-stop rule."
  },
  {
    "id": "3.4.12e",
    "type": "EXCEPTION",
    "force": null,
    "force_from": null,
    "text": "EXCEPTION TO 3.4.12c WHEN the driver is on a road with a median strip AND the driver is approaching the school bus from the front",
    "sources": [
      {
        "id": "c4",
        "quote": "If you are on a road with a median strip, only vehicles coming from behind the bus must stop."
      }
    ],
    "flags": [],
    "links": [
      "3.4.12c"
    ],
    "note": "The same passage also switches off the must-not-proceed rule for vehicles from the front on a median-strip road."
  },
  {
    "id": "3.4.12f",
    "type": "FACT",
    "force": null,
    "force_from": null,
    "text": "FACT in Ontario, school bus drivers and other witnesses can report vehicles that have illegally passed a school bus",
    "sources": [
      {
        "id": "m77",
        "quote": "In Ontario, school bus drivers and other witnesses can report vehicles that have illegally passed a school bus."
      }
    ],
    "flags": [],
    "links": [],
    "note": "\"Can report\" describes the reporting mechanism, not a permission granted to a driver, so this is a FACT."
  }
]}
